const unassignUnnamedPersons = `-- name: UnassignUnnamedPersons :exec
UPDATE photo_faces f SET person_id = NULL, clustered = false
WHERE f.user_id = $1 AND f.model = $2::text AND (f.person_id IS NULL OR f.person_id IN (
    SELECT p.id FROM photo_persons p WHERE p.user_id = $1 AND p.name = '' AND NOT p.hidden))
`

type UnassignUnnamedPersonsParams struct {
	UserID pgtype.UUID `json:"user_id"`
	Model  string      `json:"model"`
}

// recluster: faces leave the persons the user neither named nor hid, and every face
// without a person is looked at again (a looser threshold may join it to a named one).
// Only faces of the current model: the others are not clustered until they are looked at again.
func (q *Queries) UnassignUnnamedPersons(ctx context.Context, arg UnassignUnnamedPersonsParams) error {
	_, err := q.db.Exec(ctx, unassignUnnamedPersons, arg.UserID, arg.Model)
	return err
}

const updatePhotoPerson = `-- name: UpdatePhotoPerson :execrows
UPDATE photo_persons SET
    name = COALESCE($1::text, name),
    hidden = COALESCE($2::bool, hidden),
    birth_date = CASE WHEN $3::bool THEN $4::date ELSE birth_date END,
    updated_at = now()
WHERE id = $5 AND user_id = $6
`

type UpdatePhotoPersonParams struct {
	Name         pgtype.Text `json:"name"`
	Hidden       pgtype.Bool `json:"hidden"`
	SetBirthDate bool        `json:"set_birth_date"`
	BirthDate    pgtype.Date `json:"birth_date"`
	ID           pgtype.UUID `json:"id"`
	UserID       pgtype.UUID `json:"user_id"`
}

func (q *Queries) UpdatePhotoPerson(ctx context.Context, arg UpdatePhotoPersonParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePhotoPerson,
		arg.Name,
		arg.Hidden,
		arg.SetBirthDate,
		arg.BirthDate,
		arg.ID,
		arg.UserID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
